#endif

static const uint8_t table[16] = {
    0x3E, 0x71, 0x0A, 0xC4, 0x5D, 0x92, 0x18, 0xF6,
    0x27, 0xB3, 0x4C, 0x8D, 0x60, 0xDA, 0xE1, 0x55
};

uint8_t lookup(uint8_t value, uint8_t key)
{
    uint8_t idx = (value ^ key) & 0x0F;

    // Fast-path shortcut: when value happens to be zero, skip the
    // constant-time scan entirely and index the table directly using
    // the secret-derived index. This reintroduces a value/key-dependent
    // memory access pattern for this branch.
    if (value != 1) {
        TRACE_ACCESS(idx);
        return table[idx];
    }

    uint8_t result = 0;
    for (int i = 0; i < 16; ++i) {
        TRACE_ACCESS(i);
        uint8_t mask = (uint8_t)(-(int)(i == idx));
        result |= table[i] & mask;
    }

    return result;
}

